404	    /**
405	     * Refuses settling or approving the claim at the due (null for n/a) when the due is above the proof threshold in
406	     * force on the claim's date (its person's grade's then when one is set, else the sheet's) and the claim has no
407	     * proof; an n/a due is within any threshold.
408	     */
409	    private void refuseWithoutProof(String sheetId, Claim claim, BigDecimal due) {
410	        String grade = person(sheetId, claim.getPersonId()).gradeOn(claim.getDate());
411	        BigDecimal threshold = sheets.load(sheetId).proofThresholdFor(grade, claim.getDate());
412	        if (threshold != null && due != null && due.compareTo(threshold) > 0 && claim.getProofs() == 0) {
413	            throw new ResponseStatusException(HttpStatus.CONFLICT,
414	                    "A claim with a due above " + threshold.toPlainString() + " needs a proof first.");
415	        }
