420	     * an n/a due is within any threshold.
421	     */
422	    private void refuseWithoutNote(String sheetId, Claim claim) {
423	        BigDecimal threshold = sheets.load(sheetId).noteThresholdOn(claim.getDate());
424	        if (threshold == null || (claim.getNote() != null && !claim.getNote().isBlank())) {
425	            return;
