427	        BigDecimal due = due(sheetId, person(sheetId, claim.getPersonId()), claim);
428	        if (due != null && due.compareTo(threshold) > 0) {
429	            throw new ResponseStatusException(HttpStatus.CONFLICT,
430	                    "A claim with a due above " + threshold.toPlainString() + " needs a note first.");
431	        }
