608	    /**
609	     * Splits an amount (more than 0.00 and less than the claim's) off an OPEN claim: the claim keeps the rest and
610	     * loses any figure a statement bound it to; a new OPEN claim with the amount, the same date and note, the next
611	     * number, opened by the user, with a due-by from the terms in force on the date, and split from the original's
612	     * number, and a late entry when the original is, is listed as its person's newest. Refused unless the user's
613	     * role may open a claim, for a claim that is not OPEN or is deferred, for an amount out of range, and when the
614	     * original's due-by falls in a closed period (the new claim's own due-by is not judged).
615	     */
616	    @Transactional
617	    public Split split(String by, String sheetId, Long id, BigDecimal amount) {
618	        settings.refuseUnlessMay(sheetId, by, "open");
619	        Claim claim = lockedClaim(sheetId, id);
620	        if (claim.getStatus() != ClaimStatus.OPEN) {
621	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN claim can be split.");
622	        }
623	        if (claim.isDeferredOn(sheets.load(sheetId).getToday())) {
624	            throw new ResponseStatusException(HttpStatus.CONFLICT,
625	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
626	        }
627	        if (amount == null || amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
628	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
629	                    "The amount split off must be more than 0.00 and less than the claim's.");
630	        }
631	        RollupService.Snapshot before = rollup.snapshot(sheetId);
632	        Person person = person(sheetId, claim.getPersonId());
633	        claim.setAmount(claim.getAmount().subtract(scaled(amount)));
634	        claim.unbind();
635	        Claim original = claims.saveAndFlush(claim);
636	        Claim part = new Claim(sheetId, claim.getPersonId(), scaled(amount), claim.getDate(), claim.getNote());
637	        part.setRoundsOn(claim.getRoundsOn());
638	        int terms = termsFor(sheetId, person, claim.getDate());
639	        part.setDueBy(holidays.dueBy(sheetId, claim.getDate(), terms));
640	        part.setTerms(terms);
641	        part.setSplitFrom(claim.getNumber());
642	        part.setTags(claim.getTags());
643	        // a split is judged by the original alone: the part is a late entry when the original is
644	        part.setLateEntry(claim.isLateEntry());
645	        part.setStatus(ClaimStatus.OPEN);
646	        number(sheetId, part);
647	        part.setOpenedBy(by);
648	        logStatus(by, sheetId, person, part);
649	        Claim added = claims.saveAndFlush(part);
650	        audit.recordOnCommit(record("CLAIM_SPLIT", by, person, original) + " into=" + added.getNumber());
651	        audit.recordOnCommit(record("CLAIM_OPENED", by, person, added));
652	        rollup.recordChanges(by, sheetId, before);
653	        return new Split(original, added);
654	    }
