701	     * Gives the claim being opened its number: while the sheet's period numbering from is set and its today is on or
702	     * after it, the next in the sequence of the period the claim's due-by falls in (X for none), else the sheet's next.
703	     * The sheet is locked, so two claims opened at once never get the same one.
704	     */
705	    private void number(String sheetId, Claim claim) {
706	        if (!numbersByPeriod(sheetId)) {
707	            claim.setNumber(String.valueOf(sheets.nextClaimNumber(sheetId)));
708	            return;
709	        }
710	        String sequence = sequenceOn(sheetId, claim.getDueBy());
711	        Long last = claims.lastInSequence(sheetId, sequence);
712	        claim.numberIn(sequence, last == null ? 1 : last + 1);
