747	    /** The number sequence of a claim due by the date: the name of the period it is in, or X for none. */
748	    private String sequenceOn(String sheetId, LocalDate date) {
749	        return periods.findFirstBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId, date, date)
750	                .map(Period::getName).orElse(NO_PERIOD);
