753	    /**
754	     * The claim's rate figure: at the rate its person's grade in force on its date has in force on that date, rounded
755	     * as the sheet's policy date decides for it, with no floor; null (n/a) with none.
756	     */
757	    public BigDecimal rateFigure(String sheetId, Person person, Claim claim) {
758	        Sheet sheet = sheets.load(sheetId);
759	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
760	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
761	                .map(pct -> dueOn(claim.getAmount(), pct, rounding)).orElse(null);
762	    }
763	
764	    /** What a candidate rate for a grade would change: how many claims would show a different due, and by how much. */
765	    public record RatePreview(int count, BigDecimal diff) {
766	    }
767	
768	    /**
769	     * Previews the grade's rate at the percent on every date, saving nothing: the OPEN and PENDING claims whose
770	     * person has the grade in force on the claim's date and whose due would differ, and the sum of new due minus
771	     * current due (an n/a due counts as 0.00). A claim bound by a statement does not change.
772	     */
773	    @Transactional(readOnly = true)
774	    public RatePreview previewRate(String sheetId, String grade, BigDecimal pct) {
775	        Sheet sheet = sheets.load(sheetId);
776	        int count = 0;
777	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
778	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
779	            if (!claim.getStatus().isOpen() || claim.getSettledDue() != null || claim.isBound()) {
780	                continue;
781	            }
782	            Person person = person(sheetId, claim.getPersonId());
783	            if (!grade.equals(person.gradeOn(claim.getDate()))) {
784	                continue;
785	            }
786	            BigDecimal current = due(sheetId, person, claim);
787	            BigDecimal figure = dueOn(claim.getAmount(), pct, sheet.roundingOn(claim.getRoundsOn()));
788	            BigDecimal next = liveDue(figure, claim, person, sheet, true);
789	            BigDecimal before = current == null ? BigDecimal.ZERO : current;
790	            if (current == null || before.compareTo(next) != 0) {
791	                count++;
792	                diff = diff.add(next.subtract(before));
793	            }
794	        }
795	        return new RatePreview(count, diff.setScale(2));
796	    }
797	
798	    /**
799	     * The figure of the claim: its settled due, else the one a statement bound it to (not while it is pending), else
800	     * its rate figure. A statement binds this figure, under the late charge and the floor.
801	     */
802	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
803	        if (claim.getSettledDue() != null) {
804	            return claim.getSettledDue();
805	        }
806	        return claim.isBound() ? claim.getStatedDue() : rateFigure(sheetId, person, claim);
807	    }
808	
809	    /**
810	     * The due the claim shows and totals: its settled due as frozen, else its live due on its figure (the late charge
811	     * only while it is open or pending).
812	     */
813	    public BigDecimal due(String sheetId, Person person, Claim claim) {
814	        BigDecimal figure = figure(sheetId, person, claim);
815	        return claim.getSettledDue() != null ? figure
816	                : liveDue(figure, claim, person, sheets.load(sheetId), claim.getStatus().isOpen());
817	    }
818	
819	    /**
820	     * The live due of a claim on its (unfloored) figure: the greater of the floor in force on its date and the figure
821	     * plus the late charge it has gained (when charged); a correction has neither floor nor charge. Null (n/a) for an
822	     * n/a figure.
823	     */
824	    public static BigDecimal liveDue(BigDecimal figure, Claim claim, Person person, Sheet sheet, boolean charged) {
825	        if (figure == null || claim.isCorrection()) {
826	            return figure;
827	        }
828	        BigDecimal due = charged ? withLateCharge(figure, claim, person, sheet) : figure;
829	        return sheet == null ? due : floored(due, sheet.floorOn(claim.getDate()));
830	    }
831	
832	    /**
833	     * The figure (null for n/a) of the claim, with a late charge added for every full 30 days it is overdue (past its
834	     * late-from: its due-by plus its grace) by the sheet's today: for each such boundary (its late-from plus 30, 60,
835	     * 90 ... days), the sheet's late
836	     * percent in force on that boundary date of the figure plus the charges of the boundaries before it (it
837	     * compounds), rounded like its due; a boundary whose percent is 0.00 adds nothing. A deferred claim is not overdue. The charge is never bound by a statement: it keeps following the
838	     * sheet's today and its policy date.
839	     */
840	    public static BigDecimal withLateCharge(BigDecimal figure, Claim claim, Person person, Sheet sheet) {
841	        if (figure == null || sheet == null || sheet.getToday() == null || claim.isDeferredOn(sheet.getToday())) {
842	            return figure;
843	        }
844	        LocalDate lateFrom = lateFrom(claim, person, sheet);
845	        long overdue = ChronoUnit.DAYS.between(lateFrom, sheet.getToday());
846	        long periods = overdue > 0 ? overdue / 30 : 0;
847	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
848	        BigDecimal due = figure;
849	        for (long k = 1; k <= periods; k++) {
850	            BigDecimal latePct = sheet.latePctOn(lateFrom.plusDays(30 * k));
851	            if (latePct.signum() != 0) {
852	                due = due.add(dueOn(due, latePct, rounding));
853	            }
854	        }
855	        return due;
856	    }
857	
858	    /**
859	     * The date after which the claim is overdue: its due-by plus the grace days the sheet has in force on the claim's
860	     * date for its person's grade in force on that date (none: its due-by). Its late charge's 30-day boundaries count
861	     * from it; the due-by the claim shows is unchanged.
862	     */
863	    public static LocalDate lateFrom(Claim claim, Person person, Sheet sheet) {
864	        if (claim.getDueBy() == null || person == null || sheet == null) {
865	            return claim.getDueBy();
866	        }
867	        return claim.getDueBy().plusDays(sheet.graceOn(person.gradeOn(claim.getDate()), claim.getDate()));
868	    }
869	
870	    /**
871	     * Refuses a change to a claim due by the date when a closed period contains it. The sheet stays locked until
872	     * the transaction ends, so a period closing at the same moment is checked in turn.
873	     */
874	    private void refuseInClosedPeriod(String sheetId, LocalDate date) {
875	        sheets.lock(sheetId);
876	        if (periods.existsBySheetIdAndClosedTrueAndFromLessThanEqualAndToGreaterThanEqual(sheetId, date, date)) {
877	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim's due-by falls in a closed period.");
878	        }
879	    }
880	
881	    /**
882	     * The number a claim with the amount corrects: for a correction (a negative amount), the number of a settled
883	     * claim of the person, else refused; null for any other claim.
884	     */
885	    private String correctedNumber(String sheetId, Long personId, BigDecimal amount, String corrects) {
886	        if (amount.signum() >= 0) {
887	            return null;
888	        }
889	        corrects = corrects == null ? null : corrects.strip();
890	        if (corrects == null || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects,
891	                ClaimStatus.SETTLED)) {
892	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
893	                    "A negative amount must correct a settled claim of the person, named by its number.");
894	        }
895	        return corrects;
896	    }
897	
898	    /** Refuses a claim for the person dated after their retirement date; one on or before it is allowed. */
899	    private static void refuseAfterRetirement(Person person, LocalDate date) {
900	        if (person.getRetiredFrom() != null && date.isAfter(person.getRetiredFrom())) {
901	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
902	                    "That claim is dated after the person's retirement.");
903	        }
904	    }
905	
906	    private Person person(String sheetId, Long personId) {
907	        return people.findByIdAndSheetId(personId, sheetId)
908	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
909	    }
910	
911	    /**
912	     * The terms a claim of the person dated on the date has: the person's own, else those of their grade on the date,
913	     * else the sheet's on the date.
914	     */
915	    private int termsFor(String sheetId, Person person, LocalDate on) {
916	        return person.getTerms() != null ? person.getTerms()
917	                : sheets.load(sheetId).termsFor(person.gradeOn(on), on);
918	    }
919	
920	    /** The audit line about a claim; one that has a number ends with it. */
921	    private static String record(String event, String by, Person person, Claim c) {
922	        String number = c.getNumber();
923	        return event + " sheet=" + c.getSheetId() + " by=" + by + " person=" + person.getName()
924	                + " amount=" + c.getAmount().toPlainString() + " date=" + c.getDate()
925	                + (number != null ? " number=" + number : "");
926	    }
927	
928	    /**
929	     * The due on an amount at a rate: amount times rate divided by 100, rounded to two decimals the given way (a
930	     * negative amount rounds like its positive).
931	     */
932	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal pct, RoundingMode rounding) {
933	        return amount.multiply(pct).movePointLeft(2).setScale(2, rounding);
934	    }
935	
936	    /** The date a claim dated on the date rounds by: that date, or for a correction the corrected claim's date. */
937	    private LocalDate roundsOn(String sheetId, String corrects, LocalDate on) {
938	        return corrects == null ? on
939	                : claims.findBySheetIdAndNumber(sheetId, corrects).map(Claim::getDate).orElse(on);
940	    }
941	
942	    /** The due raised to the floor when it is below it. */
943	    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
944	        return floor != null && due.compareTo(floor) < 0 ? floor.setScale(2) : due;
945	    }
946	
947	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
948	        return date != null ? date : sheets.load(sheetId).getToday();
949	    }
950	
951	    /** The date, or for none the sheet's entry date, or its today when that is blank. */
952	    private LocalDate dateOrEntryDate(String sheetId, LocalDate date) {
953	        if (date != null) {
954	            return date;
955	        }
956	        Sheet sheet = sheets.load(sheetId);
957	        return sheet.getEntryDate() != null ? sheet.getEntryDate() : sheet.getToday();
958	    }
959	
960	    private static String text(BigDecimal value) {
961	        return value == null ? "n/a" : value.toPlainString();
962	    }
963	
964	    private static BigDecimal scaled(BigDecimal amount) {
965	        return amount.setScale(2, RoundingMode.UNNECESSARY);
966	    }
967	
968	    /**
969	     * The external reference a claim is to carry: stripped, or null when blank. Refused when another claim of the
970	     * sheet than the one excluded (null for none) carries it, comparing without regard to case.
971	     */
972	    private String refOf(String sheetId, String ref, Long excluded) {
973	        String stripped = ref == null ? "" : ref.strip();
974	        if (stripped.isEmpty()) {
975	            return null;
976	        }
977	        if (claims.refInUse(sheetId, stripped, excluded)) {
978	            throw new ResponseStatusException(HttpStatus.CONFLICT,
979	                    "The reference " + stripped + " is already used on the sheet.");
980	        }
981	        return stripped;
982	    }
983	
984	    private static String noteOf(String note) {
985	        return note == null ? "" : note.strip();
986	    }
987	
988	    /** Every tag ever used on a claim of the sheet, sorted. */
989	    @Transactional(readOnly = true)
990	    public List<String> tags(String sheetId) {
991	        return tags.findBySheetIdOrderByTagAsc(sheetId).stream().map(ClaimTag::getTag).toList();
992	    }
993	
994	    /** A claim's stored tags as a list, sorted; empty for none. */
995	    public static List<String> tagList(String stored) {
996	        return stored == null || stored.isEmpty() ? List.of() : List.of(stored.split(","));
997	    }
998	
999	    /** The tags a claim is to carry: each trimmed and lower-cased, repeats and blanks dropped, sorted and comma separated; null for none. */
1000	    private static String tagsOf(String tagged) {
1001	        if (tagged == null) {
1002	            return null;
1003	        }
1004	        TreeSet<String> each = new TreeSet<>();
1005	        Arrays.stream(tagged.split(",")).map(t -> t.strip().toLowerCase(Locale.ROOT)).filter(t -> !t.isEmpty())
1006	                .forEach(each::add);
1007	        if (each.stream().anyMatch(t -> t.length() > 140)) {
1008	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A tag is at most 140 characters.");
1009	        }
1010	        return each.isEmpty() ? null : String.join(",", each);
1011	    }
1012	
1013	    /** Keeps each of the tags as used on the sheet. */
1014	    private void keepTags(String sheetId, String stored) {
1015	        for (String tag : tagList(stored)) {
1016	            if (!tags.existsBySheetIdAndTag(sheetId, tag)) {
1017	                tags.saveAndFlush(new ClaimTag(sheetId, tag));
1018	            }
1019	        }
1020	    }
1021	}
